import{_ as a,C as d,o as i,c as s,ag as t,E as n}from"./chunks/framework.Drp2S_UI.js";const b=JSON.parse('{"title":"GitHub Pages 文档部署","description":"","frontmatter":{},"headers":[],"relativePath":"guide/docs-deployment.md","filePath":"guide/docs-deployment.md","lastUpdated":1792752159000}'),c={name:"guide/docs-deployment.md"};function r(l,e,p,h,g,u){const o=d("MermaidDiagram");return i(),s("div",null,[e[0]||(e[0]=t('<h1 id="github-pages-文档部署" tabindex="-1">GitHub Pages 文档部署 <a class="header-anchor" href="#github-pages-文档部署" aria-label="Permalink to &quot;GitHub Pages 文档部署&quot;">​</a></h1><p>文档使用 VitePress，源文件在 <code>docs/</code>。合并 PR 到 <code>main</code> 会触发 <code>.github/workflows/docs.yml</code>，构建静态站和在线编辑器 Demo、更新 <code>gh-pages</code> 分支，并通过 GitHub 官方 Pages Actions 部署同一份产物。工作流代码已配置；站点实际可用需要仓库所有者完成下面的 Pages 设置并成功运行工作流。</p><h2 id="仓库只需配置一次" tabindex="-1">仓库只需配置一次 <a class="header-anchor" href="#仓库只需配置一次" aria-label="Permalink to &quot;仓库只需配置一次&quot;">​</a></h2><ol><li>打开仓库 <strong>Settings → Pages → Build and deployment</strong>。</li><li>将 <strong>Source</strong> 设为 <strong>GitHub Actions</strong>。</li><li>检查 Actions 已启用，仓库规则允许工作流以 <code>GITHUB_TOKEN</code> 写入 <code>gh-pages</code>，<code>github-pages</code> environment 允许 <code>main</code> 部署。组织策略或分支保护可能限制这些权限。</li><li>合并到 <code>main</code>，或在 Actions 的 <strong>Documentation Pages</strong> 页面选择 <code>main</code> 手动运行。</li><li>在 deploy job 的 environment 链接查看实际地址。本仓库名保持 <code>canvas-editor</code> 时，预期项目站地址为 <code>https://herberthe.github.io/canvas-editor/</code>；这不是已经发布成功的声明。</li></ol><p><strong>不要选择 Deploy from a branch。</strong> GitHub 说明：由 <code>GITHUB_TOKEN</code> 推送的提交不会触发分支式 Pages 构建。因此这里将 <code>gh-pages</code> 作为可检查的静态产物分支，同时由 <code>deploy-pages</code> 正式发布，避免依赖分支推送再次触发构建。参见 <a href="https://docs.github.com/en/pages/getting-started-with-github-pages/configuring-a-publishing-source-for-your-github-pages-site" target="_blank" rel="noreferrer">GitHub Pages 发布源说明</a>。</p><p>不需要旧工作流的 SSH 服务器、HOST、USERNAME、PASSWORD 或 DOCS_PATH，也不需要为此添加 PAT。workflow 中 <code>configure-pages</code> 检查已有配置，不会用默认 token 擅自启用站点；未设置 Pages 时先配置，然后重跑失败的工作流。</p><h2 id="事件与产物流向" tabindex="-1">事件与产物流向 <a class="header-anchor" href="#事件与产物流向" aria-label="Permalink to &quot;事件与产物流向&quot;">​</a></h2>',7)),n(o,{code:`flowchart TD
  PR[针对 main 的文档相关 PR] --> Build[冻结安装、Mermaid 校验、VitePress 构建]
  Main[push main：包含合并提交] --> Build
  Manual[手动运行：选择 main] --> Build
  Build --> Gate{main 且不是 PR}
  Gate -->|否| Check[仅验证构建，不发布]
  Gate -->|是| Artifact[上传 github-pages artifact]
  Artifact --> Branch[解包同一产物并更新 gh-pages]
  Branch --> Deploy[官方 deploy-pages 发布同一 artifact]
  Deploy --> Site[github-pages environment / 文档站]
`}),e[1]||(e[1]=t(`<table tabindex="0"><thead><tr><th>job</th><th>行为</th><th>写权限</th></tr></thead><tbody><tr><td><code>build</code></td><td>Node 24、pnpm 10.32.1、冻结 lockfile 安装、检查图表、构建文档</td><td>无；<code>contents: read</code></td></tr><tr><td><code>publish-branch</code></td><td>下载 Pages artifact，提取 artifact.tar，将站点根目录同步到 gh-pages</td><td><code>contents: write</code></td></tr><tr><td><code>deploy</code></td><td>检查 Pages 配置，将相同 artifact 发布到 Pages</td><td><code>pages: write</code>、<code>id-token: write</code></td></tr></tbody></table><p>文档相关 PR 只执行构建。所有 main push 都重新构建，使渲染行为变化即使未修改 Markdown 也能重新发布。手动在其他分支运行只构建，不发布。部署使用 <code>github-pages</code> environment，同一 ref 的工作流顺序执行，避免对 gh-pages 同时写入。</p><p>产物包含根 <code>index.html</code>、<code>guide/</code>、<code>en/</code>、<code>assets/</code> 和 <code>.nojekyll</code>。<code>gh-pages</code> 仅存生成内容，不应直接编辑；文档源修改应在开发分支提交，再合并 main。<code>clean: true</code> 会移除产物中已不存在的旧页面，工作流不会强推覆盖分支历史。</p><h2 id="本地预览与路径" tabindex="-1">本地预览与路径 <a class="header-anchor" href="#本地预览与路径" aria-label="Permalink to &quot;本地预览与路径&quot;">​</a></h2><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --frozen-lockfile</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> docs:check</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> docs:build</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> docs:preview</span></span></code></pre></div><p>默认 base 为 <code>/canvas-editor/</code>，预览时访问终端地址下的 <code>/canvas-editor/</code>。构建输出是 <code>docs/.vitepress/dist</code>，其中 <code>playground/</code> 包含可独立运行的编辑器、Worker、WASM、字体和其他资源。文档首页、导航和<a href="./playground.html">在线体验</a>均提供入口。<code>docs:build</code> 已包含 Mermaid 语法校验；错误图表会让 CI 失败，不会静默以代码块代替图形。</p><p>中文入口 <code>/canvas-editor/</code>，英文入口 <code>/canvas-editor/en/</code>。搜索是构建期生成的本地索引，不需要 Algolia 密钥。Mermaid 在客户端按需加载，支持明暗主题；展开图表下的源码可复制设计。</p><h2 id="更换仓库名或自定义域名" tabindex="-1">更换仓库名或自定义域名 <a class="header-anchor" href="#更换仓库名或自定义域名" aria-label="Permalink to &quot;更换仓库名或自定义域名&quot;">​</a></h2><p>VitePress 配置读取 <code>DOCS_BASE</code>，未设置时为 <code>/canvas-editor/</code>。如果仓库改名，修改 workflow 构建步骤的 <code>DOCS_BASE</code> 为 <code>/&lt;新仓库名&gt;/</code>；本地用同样的值验证。</p><p>使用独立域名或用户根站点时通常设为 <code>/</code>，同时按 GitHub Pages 配置 DNS 和 Custom domain。如需保留域名文件，在 <code>docs/public/CNAME</code> 写入真实域名；不要只向生成分支手工添加，因为下一次 clean 发布会覆盖它。本文没有配置任何实际域名或 DNS。</p><h2 id="demo-工作流与故障排查" tabindex="-1">Demo 工作流与故障排查 <a class="header-anchor" href="#demo-工作流与故障排查" aria-label="Permalink to &quot;Demo 工作流与故障排查&quot;">​</a></h2><p><code>.github/workflows/build.yml</code> 对应用执行 lint、类型检查、单测和 Demo 构建，上传独立的 <code>canvas-editor-demo</code> artifact。文档工作流另将同一 Demo 构建到文档站的 <code>playground/</code> 子目录，不覆盖文档首页，也不再部署到上游维护者的服务器。</p><p><code>docs:dev</code> 和 <code>docs:build</code> 都会先执行 <code>scripts/build-docs-demo.mjs</code>，使用同一个 DOCS_BASE 计算 Demo 的资源前缀。临时输出在 <code>docs/public/playground/</code>，已加入 gitignore，由 VitePress 拷贝进入最终产物。该目录无需提交。文档开发服务器中的 Demo 是静态构建；修改编辑器源代码后需重新运行 <code>docs:dev</code>。</p><table tabindex="0"><thead><tr><th>现象</th><th>检查</th></tr></thead><tbody><tr><td>Pages 尚未启用或 configure-pages 失败</td><td>Settings → Pages 的 Source，启用后重跑</td></tr><tr><td>gh-pages 更新 403 / 被规则拒绝</td><td>Actions 策略、contents 写权限、gh-pages 保护与规则集</td></tr><tr><td>deploy 被 environment 阻止</td><td>github-pages 的允许分支或 required reviewers</td></tr><tr><td>首页正常，资源或子页 404</td><td>DOCS_BASE、仓库名、完整 artifact 目录和 URL 前缀</td></tr><tr><td>workflow 未出现</td><td>文件是否已合并 main、Actions 是否启用</td></tr><tr><td>PR 没有部署链接</td><td>预期行为：PR 只构建，合并 main 后发布</td></tr></tbody></table><p>工作流在 GitHub 上成功并不由本地构建替代；发布结果以对应 run 的三个 job 和 environment URL 为准。</p>`,15))])}const k=a(c,[["render",r]]);export{b as __pageData,k as default};
